import os
dart_files = []
for root, dirs, files in os.walk('lib'):
    for f in files:
        if f.endswith('.dart'):
            dart_files.append(os.path.join(root, f))
print(f'Total: {len(dart_files)}')
for f in sorted(dart_files):
    print(f)
"

