import 'package:kirakira/presentation/providers/locale_provider.dart';
import 'package:kirakira/presentation/providers/settings_providers.dart';
import 'package:kirakira/domain/services/debug_log_service.dart';
import 'package:kirakira/presentation/widgets/debug_log_overlay.dart';
import 'package:kirakira/presentation/screens/terms_dialog.dart';

/// Global navigator key for showing dialogs from anywhere
final GlobalKey<NavigatorState> rootNavigatorKey = GlobalKey<NavigatorState>();

class NativeTavernApp extends ConsumerStatefulWidget {
  const NativeTavernApp({super.key});

  @override
  ConsumerState<NativeTavernApp> createState() => _NativeTavernAppState();
}

class _NativeTavernAppState extends ConsumerState<NativeTavernApp> {
  @override
  void initState() {
    super.initState();
    // Check if debug log should be enabled on startup
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final settings = ref.read(appSettingsProvider);
      if (settings.enableDebugLog) {
        ref.read(debugLogServiceProvider).startCapturing();
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final router = ref.watch(appRouterProvider);
    final activeTheme = ref.watch(activeThemeConfigProvider);
    final locale = ref.watch(localeProvider);
    final settings = ref.watch(appSettingsProvider);
    
    // Listen for debug log setting changes
    ref.listen<AppSettings>(appSettingsProvider, (previous, next) {
      final debugLogService = ref.read(debugLogServiceProvider);
      if (next.enableDebugLog && !debugLogService.isCapturing) {
        debugLogService.startCapturing();
      } else if (!next.enableDebugLog && debugLogService.isCapturing) {
        debugLogService.stopCapturing();
      }
    });
    
    return MaterialApp.router(
      title: 'NativeTavern',
      debugShowCheckedModeBanner: false,
      theme: activeTheme.copyWith(isDark: false).toThemeData(),
      darkTheme: activeTheme.toThemeData(),
      themeMode: activeTheme.isDark ? ThemeMode.dark : ThemeMode.light,
      routerConfig: router,
      locale: const Locale('zh', 'CN'),
      localizationsDelegates: const [
        AppLocalizations.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: const [Locale('zh', 'CN')],
      builder: (context, child) {
        return DebugLogOverlayWrapper(
          enabled: settings.enableDebugLog,
          child: child ?? const SizedBox.shrink(),
        );
      },
    );
  }
}

/// Wrapper widget that shows the debug floating ball when enabled
class DebugLogOverlayWrapper extends ConsumerStatefulWidget {
  final bool enabled;
  final Widget child;

  const DebugLogOverlayWrapper({
    super.key,
    required this.enabled,
    required this.child,
  });

  @override
  ConsumerState<DebugLogOverlayWrapper> createState() => _DebugLogOverlayWrapperState();
}

class _DebugLogOverlayWrapperState extends ConsumerState<DebugLogOverlayWrapper> {
  bool _showLogViewer = false;

  void _toggleLogViewer() {
    setState(() {
      _showLogViewer = !_showLogViewer;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.enabled) {
      return widget.child;
    }

    final logs = ref.watch(currentLogsProvider);
    
    return Directionality(
      textDirection: TextDirection.ltr,
      child: Overlay(
        initialEntries: [
          OverlayEntry(
            builder: (context) => Stack(
              children: [
                widget.child,
                if (_showLogViewer)
                  Positioned.fill(
                    child: GestureDetector(
                      onTap: _toggleLogViewer,
                      child: Container(
                        color: Colors.black54,
                      ),
                    ),
                  ),
                if (_showLogViewer)
                  Positioned(
                    left: 16,
                    right: 16,
                    top: MediaQuery.of(context).padding.top + 50,
                    bottom: MediaQuery.of(context).padding.bottom + 100,
                    child: Material(
                      borderRadius: BorderRadius.circular(16),
                      clipBehavior: Clip.antiAlias,
                      child: DebugLogViewerInline(onClose: _toggleLogViewer),
                    ),
                  ),
                DebugFloatingBall(
                  logCount: logs.length,
                  onTap: _toggleLogViewer,
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:kirakira/core/logger/logger.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:kirakira/app.dart';
import 'package:kirakira/core/services/initialization_service.dart';
import 'package:kirakira/data/repositories/character_repository.dart';
import 'package:kirakira/data/repositories/chat_repository.dart';
import 'package:kirakira/data/repositories/world_info_repository.dart';
import 'package:kirakira/domain/services/llm_service.dart';
import 'package:kirakira/domain/providers/register_providers.dart';
import 'package:kirakira/domain/services/import_service.dart';
import 'package:kirakira/presentation/providers/settings_providers.dart';
import 'package:kirakira/presentation/screens/import/import_screen.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // 图片缓存上限调到200MB，角色多时减少淘汰频率
  PaintingBinding.instance.imageCache.maximumSizeBytes = 200 << 20;
  FlutterError.onError = (details) { KiraLogger().error('FLUTTER', details.exceptionAsString(), details.stack); };
  
  // Initialize core services
  final initData = await InitializationService.initialize();
  KiraLogger().init();
  registerLlmProviders();
  
  // Get shared preferences
  final prefs = await SharedPreferences.getInstance();
  
  // Create repositories
  final database = initData.database;
  final characterRepo = CharacterRepository(database, initData.dataPath);
  final chatRepo = ChatRepository(database);
  final worldInfoRepo = WorldInfoRepository(database);
  
  // Create services
  final ejsRegistry = EJSRenderRegistry();
  final llmService = LLMService(ejsRenderer: RegistryEJSRenderer(ejsRegistry));
  final importService = ImportService(initData.dataPath);
  
  runApp(
    ProviderScope(
      overrides: [
        // Database
        databaseProvider.overrideWithValue(database),
        
        // Repositories
        characterRepositoryProvider.overrideWithValue(characterRepo),
        chatRepositoryProvider.overrideWithValue(chatRepo),
        worldInfoRepositoryProvider.overrideWithValue(worldInfoRepo),
        
        // Services
        llmServiceProvider.overrideWithValue(llmService),
        ejsRenderRegistryProvider.overrideWithValue(ejsRegistry),
        importServiceProvider.overrideWithValue(importService),
        
        // Shared preferences
        sharedPreferencesProvider.overrideWithValue(prefs),
      ],
      child: const NativeTavernApp(),
    ),
  );
}

import 'dart:convert';
import 'package:flutter/material.dart';
